"""DEV225 analysis-only native local-handedness representation gate.

This derives representation contracts only.  It never computes a neighbour
correlation or examines tensor values for staggered-order outcomes.
"""
from __future__ import annotations
import hashlib, json, subprocess, sys
from pathlib import Path
import numpy as np

ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'runs/dev225_local_handedness_representation_gate'; sys.path.insert(0,str(ROOT))
from pbuf.analysis.native_handedness_representation import axial_dual, frobenius_neighbor_relation, axial_neighbor_relation

def native(x):
    if isinstance(x,np.generic): return x.item()
    if isinstance(x,np.ndarray): return x.tolist()
    if isinstance(x,dict): return {k:native(v) for k,v in x.items()}
    if isinstance(x,(tuple,list)): return [native(v) for v in x]
    return x
def dump(n,x): OUT.mkdir(parents=True,exist_ok=True); (OUT/n).write_text(json.dumps(native(x),indent=2,sort_keys=True)+'\n')
def git(*a): return subprocess.check_output(['git',*a],cwd=ROOT,text=True).strip()
def sha(p): return hashlib.sha256((ROOT/p).read_bytes()).hexdigest()
def contract(run): return json.loads((ROOT/run/'final_contract.json').read_text())
def manifest(dev,path,run): return {'dev':dev,'path':path,'run':run,'read':True,'sha256':sha(path)}

