    a={'attempt_id':'dev225_local_handedness_representation_gate','target_id':'staggered_order_representation_gate','name':'DEV225 native local handedness representation gate','aliases':['DEV225'],'summary':'Recovered the exact DEV203 antisymmetric tensor and authorized its canonical Euclidean Frobenius nearest-neighbor contraction; its axial dual is equivalent up to factor two.','why_attempted':'DEV224 representation gate selected it before any staggered-order measurement.','date_started':'2026-08-13','date_completed':'2026-08-13','dev':'DEV225','branch':git('branch','--show-current'),'files':['tools/generate_dev225_local_handedness_representation_gate.py','pbuf/analysis/native_handedness_representation.py'],'run_directories':['runs/dev225_local_handedness_representation_gate'],'tests':['tests/test_dev225_tensor_recovery.py','tests/test_dev225_axial_dual.py','tests/test_dev225_representation_equivalence.py','tests/test_dev225_reflection_covariance.py','tests/test_dev225_translation_covariance.py','tests/test_dev225_no_component_selection.py','tests/test_dev225_no_result_inspection.py','tests/test_dev225_next_gate.py'],'equations':['A_ij=(M_ij-M_ji)/2','omega=(A_yz,-A_xz,A_xy)','C_ab=A_ij(a)A_ij(b)=2 omega(a).omega(b)'],'result':'FULL','result_reason':'DEV203 fixes Euclidean native coordinates and a signed tensor; the Frobenius contraction is coefficient-free and requires neither a chosen component nor a new axis.','current_status':'CANONICAL','canonical':True,'physics_reusable':True,'infrastructure_reusable':True,'free_parameters':[],'fitted_parameters':[],'reopen_condition':'Not applicable without changed frozen input conventions.','do_not_repeat_reason':'DEV226 must use the predeclared tensor contraction, not scalar relabeling or component fishing.','evidence':[{'type':'file','value':'runs/dev225_local_handedness_representation_gate/final_contract.json'}],'confidence':'HIGH'}
